// Team Gangsta Brawl — 90s gangsta Saints, v6 "improved female torso".
// Changes:
//   • Much more detailed and natural female torso (better breast shape, waist definition, crop top layering, midriff)
//   • Improved female hip/leg proportions for better silhouette
//   • TEC-9 prop replaced with a baked real-mesh import (p_tec9.obj, Saints Row map editor export)
//   • All other functionality, animations, weapons, palettes preserved
import * as THREE from 'three';
import { SKIN_TONES, EYE_COLORS, widthScaleFor, BODY_BUILDS } from '../streetfight/characterBuilder.js';
import { loadSlicedBody, loadSlicedClothing, loadWeapon, loadAsset } from './objAssets.js';
import { SLOT_META } from './srClothing.js';
import { attachSkinning, buildSkeleton, IDENTITY_BIND } from './proceduralSkin.js';
import { getGlbGeometry, ensureGlb } from './glbAssets.js';
import { preloadCompton, cloneComptonMesh } from './comptonCharacter.js';

// iter195 — GLB character override.
//   User uploaded a Meshy "Compton Shadow Stance" GLB and asked us to
//   disable the procedural pc_body + clothing overlays and use this
//   mesh instead. When this flag is true the model factory SKIPS the
//   pc_body OBJ load, the pants overlay, and the per-vertex palette
//   painting — instead it drops a cloned Compton GLB under the `body`
//   group. The procedural skeleton (hips, knees, arms, torso, head,
//   gunMount) still exists so pose targets, gun mount, and nametag
//   anchors don't break — they just don't drive the visible mesh.
const USE_COMPTON_GLB = true;
ensureGlb().catch(() => {});

export const TEAM_COLORS = { A: 0x7c3aed, B: 0x0ea5e9 };
export const TEAM_NAMES = { A: 'SAINTS', B: 'ROLLERZ' };

function lambert(color) { return new THREE.MeshLambertMaterial({ color }); }
function skinShader(color) {
  const base = new THREE.Color(color);
  const warm = base.clone().lerp(new THREE.Color('#ffb78a'), 0.45).multiplyScalar(0.10);
  return new THREE.MeshPhongMaterial({ color: base, shininess: 10, specular: new THREE.Color(0x352822), emissive: warm });
}
function hex(c, fallback) {
  try { return new THREE.Color(c || fallback); } catch { return new THREE.Color(fallback); }
}
function buildScaleFor(b) {
  const id = b.bodyBuild || 'avg';
  return BODY_BUILDS.find(x => x.id === id) || BODY_BUILDS[1];
}

export function paletteFromBuild(build) {
  const b = build || {};
  const skin = (SKIN_TONES.find(s => s.id === b.skinId) || SKIN_TONES[2]).hex;
  const eyes = (EYE_COLORS.find(e => e.id === b.eyeColor) || EYE_COLORS[0]).hex;
  const hq = {
    eyes: hex(eyes, '#3a2417'), facePreset: b.facePreset || 'sharp',
    hairStyle: b.hairStyle || 'fade',
    facialHair: b.facialHair || (b.gender === 'female' ? 'clean' : 'stubble'),
    glasses: b.glasses || 'none', accessory: b.accessory || 'none',
    hatStyle: b.hatStyle || 'none', bodyBuild: buildScaleFor(b),
  };
  if (b.gender === 'female') {
    const shirtOn = b.fShirtOn !== false, braOn = b.fBraOn !== false;
    return {
      female: true, skin: hex(skin, '#cb9466'), hair: hex(b.fHairHex, '#143d3d'),
      bandanaOn: b.fBandanaOn !== false, wrap: hex(b.fBandanaHex, '#b91c1c'),
      torso: shirtOn ? hex(b.fShirtHex, '#e8e8e8') : (braOn ? hex(b.fBraHex, '#ec4899') : hex(skin, '#cb9466')),
      center: braOn ? hex(b.fBraHex, '#ec4899') : hex(skin, '#cb9466'),
      openJacket: shirtOn, chainOn: b.fChainOn !== false,
      hips: b.fPantsOn !== false ? hex(b.fPantsHex, '#2746a7') : hex(b.fThongHex, '#7c3aed'),
      legs: b.fPantsOn !== false ? hex(b.fPantsHex, '#2746a7') : hex(skin, '#cb9466'),
      shoes: b.fShoesOn !== false ? hex(b.fShoesHex, '#ec4899') : hex(skin, '#cb9466'),
      widthScale: widthScaleFor(b), ...hq,
      csBraOn: !!b.fCsBraOn,
      srClothing: {
        pants:      b.srPants      || 'none',
        shirt:      b.srShirt      || 'none',
        jacket:     b.srJacket     || 'none',
        hat:        b.srHat        || 'none',
        shoes:      b.srShoes      || 'none',
        socks:      b.srSocks      || 'none',
        boxers:     b.srBoxers     || 'none',
        hair:       b.srHair       || 'none',
        glasses:    b.srGlasses    || 'none',
        facialHair: b.srFacialHair || 'none',
      },
    };
  }
  const jacketOn = b.mJacketOn !== false, shirtOn = b.mShirtOn !== false;
  const underOn = b.mUnderOn !== false, sag = b.mSag || 'below';
  return {
    female: false, skin: hex(skin, '#cb9466'), hair: hex(b.mHairHex, '#2b2b33'),
    bandanaOn: b.mBandanaOn !== false, wrap: hex(b.mBandanaHex, '#7c3aed'),
    torso: jacketOn ? hex(b.mJacketHex, '#15803d') : shirtOn ? hex(b.mShirtHex, '#2746a7') : underOn ? hex(b.mUnderHex, '#e8e8e8') : hex(skin, '#cb9466'),
    center: jacketOn ? (shirtOn ? hex(b.mShirtHex, '#2746a7') : underOn ? hex(b.mUnderHex, '#e8e8e8') : hex(skin, '#cb9466'))
      : (shirtOn && underOn ? hex(b.mUnderHex, '#e8e8e8') : null),
    openJacket: jacketOn, chainOn: b.mChainOn !== false,
    hips: sag !== 'above' ? hex(b.mBoxersHex, '#ea580c') : hex(b.mPantsHex, '#15151c'),
    legs: sag !== 'none' ? hex(b.mPantsHex, '#15151c') : hex(b.mBoxersHex, '#ea580c'),
    shoes: b.mShoesOn !== false ? hex(b.mShoesHex, '#e8e8e8') : hex(skin, '#cb9466'),
    widthScale: widthScaleFor(b), ...hq,
    // SR vanilla clothing OBJ ids (per-slot, default 'none' = nothing layered)
    srClothing: {
      pants:      b.srPants      || 'none',
      shirt:      b.srShirt      || 'none',
      jacket:     b.srJacket     || 'none',
      hat:        b.srHat        || 'none',
      shoes:      b.srShoes      || 'none',
      socks:      b.srSocks      || 'none',
      boxers:     b.srBoxers     || 'none',
      hair:       b.srHair       || 'none',
      glasses:    b.srGlasses    || 'none',
      facialHair: b.srFacialHair || 'none',
    },
  };
}

export function randomBotPalette(seed) {
  const rng = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
  const skins = ['#f3d4b6', '#dca882', '#cb9466', '#a4733f', '#7b4f30', '#4a2a16'];
  const cloth = ['#15151c', '#e8e8e8', '#b91c1c', '#2746a7', '#15803d', '#eab308', '#5e5e66', '#78350f'];
  return {
    female: rng(2) === 0,
    skin: new THREE.Color(skins[rng(skins.length)]),
    hair: new THREE.Color('#1b1b22'), bandanaOn: rng(3) > 0,
    wrap: new THREE.Color(cloth[rng(cloth.length)]),
    torso: new THREE.Color(cloth[rng(cloth.length)]),
    center: new THREE.Color(cloth[rng(cloth.length)]),
    openJacket: rng(2) === 0, chainOn: rng(2) === 0,
    hips: new THREE.Color(cloth[rng(cloth.length)]),
    legs: new THREE.Color(cloth[rng(cloth.length)]),
    shoes: new THREE.Color(cloth[rng(cloth.length)]),
    widthScale: 1,
  };
}

function nameTag(label, teamColor) {
  const c = document.createElement('canvas'); c.width = 256; c.height = 40;
  const g = c.getContext('2d');
  g.fillStyle = 'rgba(0,0,0,0.55)'; g.fillRect(0, 0, 256, 40);
  g.font = 'bold 22px Chivo, sans-serif'; g.textAlign = 'center';
  g.fillStyle = `#${teamColor.toString(16).padStart(6, '0')}`;
  g.fillText(label.slice(0, 22), 128, 28);
  const tex = new THREE.CanvasTexture(c); tex.colorSpace = THREE.SRGBColorSpace;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: false }));
  sp.scale.set(2.6, 0.4, 1); sp.position.y = 2.45; return sp;
}

const METAL = () => new THREE.MeshPhongMaterial({ color: 0x23232a, shininess: 70, specular: 0x777788 });
const DARKWOOD = () => new THREE.MeshLambertMaterial({ color: 0x6b4423 });

